cat > css/styles.css <<'EOF'
/* ===== UniReg — colorful, responsive styles ===== */
:root {
  --purple: #6c5ce7;
  --blue: #0984e3;
  --teal: #00cec9;
  --green: #00b894;
  --pink: #e84393;
  --orange: #e17055;
  --yellow: #fdcb6e;
  --red: #d63031;

  --bg: #f6f4ff;
  --surface: #ffffff;
  --text: #2d3047;
  --muted: #6b6f85;
  --border: #e6e3f5;

  --grad-main: linear-gradient(135deg, #6c5ce7 0%, #a55eea 35%, #e84393 70%, #fd9644 100%);
  --radius: 16px;
  --radius-sm: 10px;
  --shadow: 0 10px 30px rgba(108, 92, 231, 0.12);
  --shadow-lg: 0 20px 50px rgba(108, 92, 231, 0.22);
  --nav-h: 68px;
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at 10% 0%, rgba(232, 67, 147, 0.07), transparent 40%),
    radial-gradient(circle at 90% 30%, rgba(9, 132, 227, 0.07), transparent 40%),
    var(--bg);
  line-height: 1.55;
}
body.no-scroll { overflow: hidden; }
main { flex: 1; }
h1, h2, h3, h4 { line-height: 1.2; margin: 0 0 .5em; }
a { color: var(--purple); }
img { max-width: 100%; }

.container { width: min(1200px, 100% - 2.5rem); margin-inline: auto; }
.section { margin-block: 3.5rem; }
.center { text-align: center; }
.muted { color: var(--muted); }
.small { font-size: .85rem; }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.gradient-text {
  background: linear-gradient(90deg, #ffeaa7, #fab1a0, #81ecec);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}

/* ===== Buttons ===== */
.btn {
  --btn-bg: #fff;
  display: inline-flex; align-items: center; justify-content: center; gap: .4rem;
  padding: .7rem 1.25rem;
  border: 2px solid transparent;
  border-radius: 999px;
  background: var(--btn-bg);
  color: var(--text);
  font: inherit; font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: transform .15s ease, box-shadow .2s ease, background .2s ease, opacity .2s;
  white-space: nowrap;
}
.btn:hover:not(:disabled) { transform: translateY(-2px); }
.btn:focus-visible { outline: 3px solid var(--yellow); outline-offset: 2px; }
.btn:disabled { opacity: .55; cursor: not-allowed; }
.btn-primary { background: var(--grad-main); background-size: 150% 150%; color: #fff; box-shadow: 0 6px 18px rgba(232, 67, 147, .35); }
.btn-primary:hover:not(:disabled) { background-position: 100% 0; box-shadow: 0 10px 24px rgba(232, 67, 147, .45); }
.btn-success { background: linear-gradient(135deg, #00b894, #55efc4); color: #fff; }
.btn-danger { background: linear-gradient(135deg, #d63031, #ff7675); color: #fff; }
.btn-ghost { background: transparent; border-color: var(--border); color: var(--text); }
.btn-ghost:hover:not(:disabled) { border-color: var(--purple); color: var(--purple); }
.btn-light { background: #fff; color: var(--purple); }
.btn-outline-light { background: rgba(255, 255, 255, .12); border-color: rgba(255, 255, 255, .7); color: #fff; }
.btn-sm { padding: .4rem .85rem; font-size: .85rem; }
.btn-lg { padding: .9rem 1.6rem; font-size: 1.05rem; }

/* ===== Navbar ===== */
.navbar {
  position: sticky; top: 0; z-index: 50;
  height: var(--nav-h);
  background: rgba(255, 255, 255, .85);
  backdrop-filter: blur(12px);
  border-bottom: 3px solid transparent;
  border-image: var(--grad-main) 1;
  box-shadow: 0 4px 20px rgba(0, 0, 0, .05);
}
.nav-inner { height: 100%; display: flex; align-items: center; justify-content: space-between; }
.brand { display: flex; align-items: center; gap: .5rem; text-decoration: none; color: var(--text); font-size: 1.4rem; }
.brand-logo {
  display: grid; place-items: center; width: 42px; height: 42px;
  border-radius: 12px; background: var(--grad-main); font-size: 1.3rem;
  box-shadow: 0 4px 12px rgba(108, 92, 231, .4);
}
.brand-text strong { background: var(--grad-main); -webkit-background-clip: text; background-clip: text; color: transparent; }
.nav-menu { display: flex; gap: .35rem; }
.nav-link {
  position: relative;
  display: flex; align-items: center; gap: .35rem;
  padding: .55rem 1rem; border-radius: 999px;
  color: var(--text); text-decoration: none; font-weight: 600; font-size: .95rem;
  transition: background .2s, color .2s;
}
.nav-link:hover { background: #f0edff; color: var(--purple); }
.nav-link.active { background: var(--grad-main); color: #fff; box-shadow: 0 4px 14px rgba(232, 67, 147, .35); }
.nav-badge {
  min-width: 20px; height: 20px; padding: 0 6px;
  display: inline-grid; place-items: center;
  border-radius: 999px; background: var(--yellow); color: #2d3047;
  font-size: .72rem; font-weight: 800;
}
.nav-toggle { display: none; background: none; border: 0; padding: .5rem; cursor: pointer; }
.nav-toggle span { display: block; width: 26px; height: 3px; margin: 5px 0; border-radius: 3px; background: var(--purple); transition: transform .25s, opacity .25s; }
.nav-toggle.open span:nth-child(1) { transform: translateY(8px) rotate(45deg); }
.nav-toggle.open span:nth-child(2) { opacity: 0; }
.nav-toggle.open span:nth-child(3) { transform: translateY(-8px) rotate(-45deg); }

/* ===== Hero (home) ===== */
.hero {
  position: relative; overflow: hidden;
  padding: 5rem 0 6.5rem;
  background: var(--grad-main);
  color: #fff;
}
.hero-inner { position: relative; z-index: 1; text-align: center; }
.hero h1 { font-size: clamp(2rem, 5vw, 3.4rem); }
.hero-sub { font-size: 1.15rem; max-width: 620px; margin: 0 auto 2rem; opacity: .95; }
.eyebrow {
  display: inline-block; margin: 0 0 1rem;
  padding: .35rem 1rem; border-radius: 999px;
  background: rgba(255, 255, 255, .2); font-weight: 600; font-size: .9rem;
}
.hero-search {
  display: flex; gap: .5rem;
  max-width: 640px; margin: 0 auto 1.5rem; padding: .45rem;
  background: #fff; border-radius: 999px; box-shadow: var(--shadow-lg);
}
.hero-search input { flex: 1; min-width: 0; border: 0; padding: .6rem 1.1rem; font: inherit; font-size: 1rem; background: transparent; outline: none; color: var(--text); }
.hero-actions { display: flex; flex-wrap: wrap; gap: .75rem; justify-content: center; }
.blob { position: absolute; border-radius: 50%; filter: blur(60px); opacity: .55; animation: float 12s ease-in-out infinite; }
.blob-1 { width: 320px; height: 320px; background: #00cec9; top: -80px; left: -60px; }
.blob-2 { width: 260px; height: 260px; background: #fdcb6e; bottom: -90px; right: 10%; animation-delay: -4s; }
.blob-3 { width: 200px; height: 200px; background: #0984e3; top: 30%; right: -50px; animation-delay: -8s; }
@keyframes float { 50% { transform: translate(30px, -25px) scale(1.1); } }

/* ===== Page header (inner pages) ===== */
.page-header {
  padding: 3rem 0 4.5rem;
  background: linear-gradient(135deg, var(--from), var(--to));
  color: #fff;
  clip-path: ellipse(120% 100% at 50% 0%);
}
.page-header h1 { font-size: clamp(1.8rem, 4vw, 2.6rem); }
.page-header p { margin: 0; opacity: .95; font-size: 1.05rem; }

/* ===== Stat cards ===== */
.stats {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.25rem;
  margin-top: -3.5rem; position: relative; z-index: 2;
}
.stats.mini { margin-top: 0; }
.stat-card {
  display: flex; flex-direction: column; align-items: flex-start; gap: .15rem;
  padding: 1.25rem 1.4rem;
  background: var(--surface);
  border-radius: var(--radius);
  border-top: 5px solid var(--accent);
  box-shadow: var(--shadow);
}
.stat-card strong { font-size: 2rem; color: var(--accent); }
.stat-card strong.text-stat { font-size: 1.25rem; padding-block: .45rem; }
.stat-card span:last-child { color: var(--muted); font-size: .9rem; }
.stat-icon {
  width: 42px; height: 42px; display: grid; place-items: center;
  border-radius: 12px; font-size: 1.3rem;
  background: color-mix(in srgb, var(--accent) 15%, white);
}

/* ===== Section headings ===== */
.section-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; flex-wrap: wrap; margin-bottom: 1.25rem; }
.section-head h2 { margin: 0; }
.link-arrow { font-weight: 600; text-decoration: none; }
.link-arrow:hover { text-decoration: underline; }

/* ===== Department tiles ===== */
.dept-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 1rem; }
.dept-tile {
  display: flex; flex-direction: column; align-items: center; gap: .3rem;
  padding: 1.4rem 1rem; text-align: center; text-decoration: none; color: var(--text);
  border-radius: var(--radius);
  background: linear-gradient(160deg, color-mix(in srgb, var(--dept) 18%, white), #fff 70%);
  border: 2px solid color-mix(in srgb, var(--dept) 35%, white);
  transition: transform .2s, box-shadow .2s;
}
.dept-tile:hover { transform: translateY(-5px) rotate(-1deg); box-shadow: 0 12px 26px color-mix(in srgb, var(--dept) 35%, transparent); }
.dept-icon { font-size: 2rem; }
.dept-name { font-weight: 700; }
.dept-count { font-size: .8rem; color: var(--muted); }

/* ===== Steps ===== */
.steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.25rem; margin-top: 1.5rem; }
.step { background: var(--surface); border-radius: var(--radius); padding: 1.5rem; box-shadow: var(--shadow); border-bottom: 5px solid var(--accent); }
.step-num {
  display: grid; place-items: center; width: 44px; height: 44px; margin-bottom: .75rem;
  border-radius: 50%; background: var(--accent); color: #fff; font-weight: 800; font-size: 1.2rem;
}
.step p { margin: 0; color: var(--muted); }

/* ===== Filter panel ===== */
.filter-panel {
  margin-top: -2.5rem; position: relative; z-index: 2;
  padding: 1.5rem; background: var(--surface);
  border-radius: var(--radius); box-shadow: var(--shadow-lg);
}
.search-box { position: relative; margin-bottom: 1rem; }
.search-box.small { margin: 0; flex: 1; }
.search-icon { position: absolute; left: 1rem; top: 50%; transform: translateY(-50%); pointer-events: none; }
.search-box input {
  width: 100%; padding: .9rem 1rem .9rem 2.8rem;
  border: 2px solid var(--border); border-radius: 999px;
  font: inherit; font-size: 1rem; background: #faf9ff;
  transition: border-color .2s, box-shadow .2s;
}
.search-box.small input { padding-block: .6rem; }
.search-box input:focus { outline: none; border-color: var(--purple); box-shadow: 0 0 0 4px rgba(108, 92, 231, .15); }
.filters { display: grid; grid-template-columns: repeat(5, 1fr); gap: 1rem; }
.filter label { display: block; font-size: .8rem; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin-bottom: .3rem; }
select, .field input, .field select {
  width: 100%; padding: .65rem .9rem;
  border: 2px solid var(--border); border-radius: var(--radius-sm);
  background: #faf9ff; font: inherit; color: var(--text);
  transition: border-color .2s, box-shadow .2s;
}
select { cursor: pointer; }
select:focus, .field input:focus { outline: none; border-color: var(--purple); box-shadow: 0 0 0 4px rgba(108, 92, 231, .15); }
.filter-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 1rem; gap: 1rem; flex-wrap: wrap; }

/* Toggle switch */
.switch { display: inline-flex; align-items: center; gap: .6rem; cursor: pointer; font-weight: 600; }
.switch input { position: absolute; opacity: 0; }
.slider { position: relative; width: 46px; height: 26px; border-radius: 999px; background: #d8d4ef; transition: background .2s; }
.slider::after { content: ""; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: #fff; box-shadow: 0 2px 4px rgba(0,0,0,.2); transition: transform .2s; }
.switch input:checked + .slider { background: var(--green); }
.switch input:checked + .slider::after { transform: translateX(20px); }
.switch input:focus-visible + .slider { outline: 3px solid var(--yellow); outline-offset: 2px; }

.results-bar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; margin: 1.75rem 0 1rem; }
.result-count { margin: 0; font-weight: 700; font-size: 1.05rem; }
.active-filters { display: flex; flex-wrap: wrap; gap: .4rem; }
.filter-chip { padding: .3rem .8rem; border-radius: 999px; font-size: .8rem; font-weight: 600; background: #ede9ff; color: var(--purple); }

/* ===== Course cards ===== */
.course-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 1.5rem; margin-bottom: 3rem; }
.course-card {
  display: flex; flex-direction: column;
  padding: 1.4rem;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border-top: 6px solid var(--dept);
  position: relative; overflow: hidden;
  transition: transform .2s, box-shadow .2s;
  animation: pop .35s ease both;
}
.course-card::before {
  content: ""; position: absolute; top: -60px; right: -60px; width: 140px; height: 140px;
  border-radius: 50%; background: var(--dept); opacity: .1; pointer-events: none;
}
.course-card:hover { transform: translateY(-6px); box-shadow: 0 18px 36px color-mix(in srgb, var(--dept) 30%, transparent); }
@keyframes pop { from { opacity: 0; transform: translateY(12px) scale(.98); } }
.card-top { display: flex; justify-content: space-between; align-items: center; gap: .5rem; margin-bottom: .8rem; }
.dept-chip {
  display: inline-flex; align-items: center; gap: .3rem;
  padding: .25rem .7rem; border-radius: 999px;
  font-size: .78rem; font-weight: 700;
  background: color-mix(in srgb, var(--dept) 16%, white);
  color: color-mix(in srgb, var(--dept) 80%, black);
}
.credit-chip { padding: .2rem .6rem; border-radius: 8px; font-size: .78rem; font-weight: 800; background: var(--dept); color: #fff; }
.card-title { font-size: 1.15rem; }
.course-code { display: block; font-size: .85rem; color: var(--dept); letter-spacing: .05em; filter: brightness(.85); }
.card-desc { margin: 0 0 .9rem; color: var(--muted); font-size: .92rem; flex: 1; }
.card-meta { list-style: none; padding: 0; margin: 0 0 1rem; display: grid; gap: .25rem; font-size: .88rem; }
.capacity { display: flex; align-items: center; gap: .75rem; margin-bottom: 1rem; }
.capacity-bar { flex: 1; height: 8px; border-radius: 999px; background: #eeeaf8; overflow: hidden; }
.capacity-bar span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--dept), color-mix(in srgb, var(--dept) 55%, white)); }
.seat-badge { padding: .2rem .6rem; border-radius: 999px; font-size: .75rem; font-weight: 700; white-space: nowrap; }
.seat-badge.ok { background: #d5f5ec; color: #00795f; }
.seat-badge.low { background: #fff1d0; color: #9a6a00; }
.seat-badge.full { background: #ffe0e0; color: #b71c1c; }
.card-actions { display: flex; gap: .6rem; }
.card-actions .btn { flex: 1; }

/* ===== Cards / forms ===== */
.card { background: var(--surface); border-radius: var(--radius); box-shadow: var(--shadow); padding: 1.5rem; }
.register-layout { display: grid; grid-template-columns: 1fr 320px; gap: 1.5rem; align-items: start; margin-top: -2.5rem; position: relative; z-index: 2; }
.form-card fieldset { border: 0; padding: 0; margin: 0 0 1.75rem; }
.form-card fieldset:last-child { margin-bottom: 0; }
legend { display: flex; align-items: center; gap: .6rem; font-size: 1.2rem; font-weight: 700; margin-bottom: 1rem; padding: 0; }
.legend-num { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: var(--grad-main); color: #fff; font-size: .95rem; }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem 1.25rem; }
.field label { display: block; font-weight: 600; font-size: .9rem; margin-bottom: .3rem; }
.field-error { display: block; min-height: 1.1em; color: var(--red); font-size: .8rem; margin-top: .2rem; }
.field-error.block:empty { min-height: 0; margin: 0; }
.field.invalid input, .field.invalid select { border-color: var(--red); background: #fff5f5; }
.form-actions { display: flex; justify-content: flex-end; gap: .75rem; margin-top: 1.25rem; flex-wrap: wrap; }
.form-actions.full { grid-column: 1 / -1; margin-top: .25rem; }
.checkbox { display: flex; gap: .6rem; align-items: flex-start; cursor: pointer; }
.checkbox input { width: 18px; height: 18px; margin-top: .2rem; accent-color: var(--purple); }

.option-filters { display: flex; gap: .75rem; margin-bottom: 1rem; }
.option-filters select { width: auto; min-width: 180px; }
.course-options { display: grid; gap: .6rem; max-height: 440px; overflow-y: auto; padding: .25rem; margin: -.25rem; }
.course-option {
  display: flex; align-items: center; gap: .85rem;
  padding: .8rem 1rem;
  border: 2px solid var(--border); border-left: 6px solid var(--dept);
  border-radius: var(--radius-sm);
  cursor: pointer; transition: border-color .15s, background .15s, transform .15s;
}
.course-option:hover:not(.disabled) { transform: translateX(3px); border-color: color-mix(in srgb, var(--dept) 50%, white); border-left-color: var(--dept); }
.course-option:has(input:checked) { background: color-mix(in srgb, var(--dept) 10%, white); border-color: var(--dept); }
.course-option.disabled { opacity: .55; cursor: not-allowed; }
.course-option input { width: 20px; height: 20px; flex-shrink: 0; accent-color: var(--dept); }
.option-body { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.option-title { font-size: .95rem; }
.option-meta { font-size: .8rem; color: var(--muted); }

.summary-card { position: sticky; top: calc(var(--nav-h) + 1rem); border-top: 6px solid var(--teal); }
.summary-row { display: flex; justify-content: space-between; gap: 1rem; padding: .45rem 0; font-size: .92rem; }
.summary-row.total { border-top: 2px dashed var(--border); margin-top: .4rem; padding-top: .7rem; font-size: 1rem; }
.credit-meter { height: 12px; border-radius: 999px; background: #eeeaf8; overflow: hidden; margin: .6rem 0; }
.credit-meter span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--green), var(--teal), var(--blue)); transition: width .3s; }
.credit-meter.over span { background: linear-gradient(90deg, var(--orange), var(--red)); }
.warning-list { list-style: none; padding: .7rem .9rem; margin: .75rem 0 0; background: #fff6e5; border-radius: var(--radius-sm); font-size: .82rem; color: #8a5a00; display: grid; gap: .3rem; }

/* ===== Data table ===== */
.table-card { padding: 0; overflow: hidden; }
.table-wrap { overflow-x: auto; }
.data-table { width: 100%; border-collapse: collapse; font-size: .92rem; }
.data-table thead th {
  text-align: left; padding: 1rem; white-space: nowrap;
  background: var(--grad-main); color: #fff; font-weight: 700; font-size: .82rem; text-transform: uppercase; letter-spacing: .04em;
}
.data-table td { padding: .9rem 1rem; border-bottom: 1px solid var(--border); }
.data-table tbody tr { transition: background .15s; }
.data-table tbody tr:nth-child(even) { background: #faf9ff; }
.data-table tbody tr:hover { background: color-mix(in srgb, var(--dept) 8%, white); }
.data-table tbody td:first-child { border-left: 5px solid var(--dept); }
.data-table tfoot td { padding: 1rem; font-weight: 600; background: #f3f0ff; }
.code-pill { display: inline-block; padding: .2rem .6rem; border-radius: 8px; background: var(--dept); color: #fff; font-weight: 700; font-size: .8rem; }

.empty-state { text-align: center; padding: 2.5rem 1.5rem; }
.empty-state.wide { grid-column: 1 / -1; background: var(--surface); border-radius: var(--radius); box-shadow: var(--shadow); }
.empty-icon { font-size: 3rem; margin-bottom: .5rem; }
.empty-state p { color: var(--muted); }

/* ===== Profile ===== */
.profile-layout { display: grid; grid-template-columns: 320px 1fr; gap: 1.5rem; align-items: start; margin-top: -2.5rem; position: relative; z-index: 2; }
.profile-main { display: grid; gap: 1.5rem; min-width: 0; }
.profile-card { text-align: center; position: relative; overflow: hidden; padding-top: 0; }
.profile-card::before { content: ""; display: block; height: 90px; margin: 0 -1.5rem; background: linear-gradient(135deg, #e84393, #fdcb6e, #00cec9); }
.avatar {
  width: 104px; height: 104px; margin: -52px auto .75rem;
  display: grid; place-items: center; border-radius: 50%;
  background: var(--grad-main); color: #fff; font-size: 2.2rem; font-weight: 800;
  border: 5px solid #fff; box-shadow: var(--shadow);
}
.profile-card h2 { margin-bottom: .2rem; }
.profile-info { list-style: none; padding: 0; margin: 1.25rem 0 0; text-align: left; display: grid; gap: .6rem; }
.profile-info li { display: flex; flex-direction: column; padding: .65rem .85rem; border-radius: var(--radius-sm); background: #faf9ff; }
.profile-info li:nth-child(1) { border-left: 4px solid var(--purple); }
.profile-info li:nth-child(2) { border-left: 4px solid var(--blue); }
.profile-info li:nth-child(3) { border-left: 4px solid var(--green); }
.profile-info li:nth-child(4) { border-left: 4px solid var(--pink); }
.profile-info span { font-size: .78rem; color: var(--muted); }
.profile-info strong { word-break: break-word; }

.weekly-schedule { display: grid; grid-template-columns: repeat(5, 1fr); gap: .75rem; }
.day-col { background: #faf9ff; border-radius: var(--radius-sm); padding: .75rem; min-height: 140px; }
.day-col h4 { text-align: center; margin-bottom: .6rem; color: var(--purple); }
.slot {
  display: flex; flex-direction: column; padding: .55rem .65rem; margin-bottom: .5rem;
  border-radius: 8px; font-size: .8rem;
  background: color-mix(in srgb, var(--dept) 15%, white);
  border-left: 4px solid var(--dept);
}
.slot strong { color: color-mix(in srgb, var(--dept) 75%, black); }
.slot small { color: var(--muted); }
.slot-empty { text-align: center; font-size: .8rem; color: var(--muted); margin: 1.5rem 0 0; }

.edit-card summary { cursor: pointer; list-style: none; display: flex; align-items: center; justify-content: space-between; }
.edit-card summary::-webkit-details-marker { display: none; }
.edit-card summary::after { content: "▾"; font-size: 1.2rem; color: var(--purple); transition: transform .2s; }
.edit-card[open] summary::after { transform: rotate(180deg); }
.edit-card summary h3 { margin: 0; }
.edit-card[open] summary { margin-bottom: 1.25rem; }

/* ===== Modal ===== */
.modal-overlay {
  position: fixed; inset: 0; z-index: 100;
  display: grid; place-items: center; padding: 1rem;
  background: rgba(45, 48, 71, .55); backdrop-filter: blur(4px);
  opacity: 0; transition: opacity .2s;
}
.modal-overlay[hidden] { display: none; }
.modal-overlay.show { opacity: 1; }
.modal {
  width: min(520px, 100%); max-height: 90vh; overflow-y: auto;
  background: var(--surface); border-radius: 20px; box-shadow: 0 30px 70px rgba(0, 0, 0, .3);
  transform: translateY(20px) scale(.96); transition: transform .25s cubic-bezier(.2, .9, .3, 1.3);
}
.modal-overlay.show .modal { transform: none; }
.modal-header {
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  padding: 1.1rem 1.5rem; background: var(--grad-main); color: #fff;
}
.modal-error .modal-header { background: linear-gradient(135deg, #d63031, #e17055); }
.modal-header h2 { margin: 0; font-size: 1.2rem; }
.modal-close { background: rgba(255, 255, 255, .2); border: 0; color: #fff; width: 34px; height: 34px; border-radius: 50%; font-size: 1.4rem; line-height: 1; cursor: pointer; }
.modal-close:hover { background: rgba(255, 255, 255, .35); }
.modal-body { padding: 1.5rem; }
.modal-body > p:first-child { margin-top: 0; }
.modal-footer { display: flex; justify-content: flex-end; gap: .75rem; padding: 0 1.5rem 1.5rem; flex-wrap: wrap; }
.confirm-list { list-style: none; padding: 0; margin: 0 0 1rem; display: grid; gap: .5rem; }
.confirm-list li { display: flex; flex-direction: column; padding: .7rem .9rem; border-radius: var(--radius-sm); background: color-mix(in srgb, var(--dept) 12%, white); border-left: 5px solid var(--dept); }
.confirm-list small { color: var(--muted); }
.confirm-total { display: flex; justify-content: space-between; padding: .8rem 1rem; border-radius: var(--radius-sm); background: #f3f0ff; }
.confirm-total strong { color: var(--purple); }
.error-list { padding-left: 1.2rem; color: #b71c1c; display: grid; gap: .3rem; }
.details p { color: var(--muted); }
.details-grid { display: grid; grid-template-columns: auto 1fr; gap: .5rem 1rem; margin: 0; }
.details-grid dt { font-weight: 700; color: var(--dept); filter: brightness(.85); }
.details-grid dd { margin: 0; display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; }

/* ===== Toasts ===== */
.toast-stack { position: fixed; bottom: 1.25rem; right: 1.25rem; z-index: 200; display: grid; gap: .5rem; }
.toast {
  padding: .85rem 1.2rem; border-radius: 12px; color: #fff; font-weight: 600;
  box-shadow: 0 10px 30px rgba(0, 0, 0, .2);
  animation: slideIn .3s ease both; transition: opacity .3s, transform .3s;
}
.toast.hide { opacity: 0; transform: translateX(30px); }
.toast-success { background: linear-gradient(135deg, #00b894, #00cec9); }
.toast-warn { background: linear-gradient(135deg, #e17055, #fdcb6e); }
.toast-error { background: linear-gradient(135deg, #d63031, #e84393); }
@keyframes slideIn { from { opacity: 0; transform: translateX(30px); } }

/* ===== Footer ===== */
.footer { margin-top: 3rem; padding: 2rem 0; background: #2d3047; color: #e8e6f5; border-top: 5px solid transparent; border-image: var(--grad-main) 1; }
.footer-inner { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; }
.footer p { margin: 0; }
.footer .muted { color: #a9a7c4; }
.footer a { color: #81ecec; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .filters { grid-template-columns: repeat(3, 1fr); }
  .steps { grid-template-columns: repeat(2, 1fr); }
  .register-layout, .profile-layout { grid-template-columns: 1fr; }
  .summary-card { position: static; order: -1; }
  .profile-card { max-width: 520px; width: 100%; margin-inline: auto; }
}

@media (max-width: 860px) {
  .nav-toggle { display: block; }
  .nav-menu {
    position: absolute; top: var(--nav-h); left: 0; right: 0;
    flex-direction: column; gap: .25rem; padding: 1rem;
    background: #fff; box-shadow: 0 16px 30px rgba(0, 0, 0, .1);
    transform: translateY(-10px); opacity: 0; visibility: hidden;
    transition: transform .2s, opacity .2s, visibility .2s;
  }
  .nav-menu.open { transform: none; opacity: 1; visibility: visible; }
  .nav-link { padding: .8rem 1rem; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .weekly-schedule { grid-template-columns: 1fr; }
  .day-col { min-height: 0; }
  .slot-empty { margin: 0; }

  /* Data table collapses into stacked cards */
  .data-table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
  .data-table, .data-table tbody, .data-table tr, .data-table td, .data-table tfoot { display: block; width: 100%; }
  .data-table tbody tr { border-left: 6px solid var(--dept); border-bottom: 1px solid var(--border); padding: .5rem 0; }
  .data-table tbody td:first-child { border-left: 0; }
  .data-table td { display: flex; justify-content: space-between; gap: 1rem; padding: .45rem 1rem; border: 0; text-align: right; }
  .data-table td::before { content: attr(data-label); font-weight: 700; color: var(--muted); text-align: left; }
  .data-table tfoot tr { display: flex; justify-content: space-between; }
  .data-table tfoot td { width: auto; }
}

@media (max-width: 600px) {
  .container { width: calc(100% - 1.5rem); }
  .hero { padding: 3.5rem 0 5.5rem; }
  .hero-search { flex-direction: column; border-radius: var(--radius); }
  .hero-search .btn { width: 100%; }
  .filters, .form-grid { grid-template-columns: 1fr; }
  .option-filters { flex-direction: column; }
  .option-filters select { width: 100%; }
  .stats { gap: .75rem; }
  .stat-card { padding: 1rem; }
  .stat-card strong { font-size: 1.6rem; }
  .steps { grid-template-columns: 1fr; }
  .course-grid { grid-template-columns: 1fr; }
  .form-actions { flex-direction: column-reverse; }
  .form-actions .btn { width: 100%; }
  .modal-footer .btn { flex: 1; }
  .course-option { flex-wrap: wrap; }
  .toast-stack { left: .75rem; right: .75rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
EOF

toolu_01T7afemxqyEbcsGi72gkpAD.command:
cd /work && cat > css/styles.css <<'EOF'
/* ===== UniReg — colorful, responsive styles ===== */
:root {
  --purple: #6c5ce7;
  --blue: #0984e3;
  --teal: #00cec9;
  --green: #00b894;
  --pink: #e84393;
  --orange: #e17055;
  --yellow: #fdcb6e;
  --red: #d63031;

  --bg: #f6f4ff;
  --surface: #ffffff;
  --text: #2d3047;
  --muted: #6b6f85;
  --border: #e6e3f5;

  --grad-main: linear-gradient(135deg, #6c5ce7 0%, #a55eea 35%, #e84393 70%, #fd9644 100%);
  --radius: 16px;
  --radius-sm: 10px;
  --shadow: 0 10px 30px rgba(108, 92, 231, 0.12);
  --shadow-lg: 0 20px 50px rgba(108, 92, 231, 0.22);
  --nav-h: 68px;
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at 10% 0%, rgba(232, 67, 147, 0.07), transparent 40%),
    radial-gradient(circle at 90% 30%, rgba(9, 132, 227, 0.07), transparent 40%),
    var(--bg);
  line-height: 1.55;
}
body.no-scroll { overflow: hidden; }
main { flex: 1; }
h1, h2, h3, h4 { line-height: 1.2; margin: 0 0 .5em; }
a { color: var(--purple); }
img { max-width: 100%; }

.container { width: min(1200px, 100% - 2.5rem); margin-inline: auto; }
.section { margin-block: 3.5rem; }
.center { text-align: center; }
.muted { color: var(--muted); }
.small { font-size: .85rem; }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.gradient-text {
  background: linear-gradient(90deg, #ffeaa7, #fab1a0, #81ecec);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}

/* ===== Buttons ===== */
.btn {
  --btn-bg: #fff;
  display: inline-flex; align-items: center; justify-content: center; gap: .4rem;
  padding: .7rem 1.25rem;
  border: 2px solid transparent;
  border-radius: 999px;
  background: var(--btn-bg);
  color: var(--text);
  font: inherit; font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: transform .15s ease, box-shadow .2s ease, background .2s ease, opacity .2s;
  white-space: nowrap;
}
.btn:hover:not(:disabled) { transform: translateY(-2px); }
.btn:focus-visible { outline: 3px solid var(--yellow); outline-offset: 2px; }
.btn:disabled { opacity: .55; cursor: not-allowed; }
.btn-primary { background: var(--grad-main); background-size: 150% 150%; color: #fff; box-shadow: 0 6px 18px rgba(232, 67, 147, .35); }
.btn-primary:hover:not(:disabled) { background-position: 100% 0; box-shadow: 0 10px 24px rgba(232, 67, 147, .45); }
.btn-success { background: linear-gradient(135deg, #00b894, #55efc4); color: #fff; }
.btn-danger { background: linear-gradient(135deg, #d63031, #ff7675); color: #fff; }
.btn-ghost { background: transparent; border-color: var(--border); color: var(--text); }
.btn-ghost:hover:not(:disabled) { border-color: var(--purple); color: var(--purple); }
.btn-light { background: #fff; color: var(--purple); }
.btn-outline-light { background: rgba(255, 255, 255, .12); border-color: rgba(255, 255, 255, .7); color: #fff; }
.btn-sm { padding: .4rem .85rem; font-size: .85rem; }
.btn-lg { padding: .9rem 1.6rem; font-size: 1.05rem; }

/* ===== Navbar ===== */
.navbar {
  position: sticky; top: 0; z-index: 50;
  height: var(--nav-h);
  background: rgba(255, 255, 255, .85);
  backdrop-filter: blur(12px);
  border-bottom: 3px solid transparent;
  border-image: var(--grad-main) 1;
  box-shadow: 0 4px 20px rgba(0, 0, 0, .05);
}
.nav-inner { height: 100%; display: flex; align-items: center; justify-content: space-between; }
.brand { display: flex; align-items: center; gap: .5rem; text-decoration: none; color: var(--text); font-size: 1.4rem; }
.brand-logo {
  display: grid; place-items: center; width: 42px; height: 42px;
  border-radius: 12px; background: var(--grad-main); font-size: 1.3rem;
  box-shadow: 0 4px 12px rgba(108, 92, 231, .4);
}
.brand-text strong { background: var(--grad-main); -webkit-background-clip: text; background-clip: text; color: transparent; }
.nav-menu { display: flex; gap: .35rem; }
.nav-link {
  position: relative;
  display: flex; align-items: center; gap: .35rem;
  padding: .55rem 1rem; border-radius: 999px;
  color: var(--text); text-decoration: none; font-weight: 600; font-size: .95rem;
  transition: background .2s, color .2s;
}
.nav-link:hover { background: #f0edff; color: var(--purple); }
.nav-link.active { background: var(--grad-main); color: #fff; box-shadow: 0 4px 14px rgba(232, 67, 147, .35); }
.nav-badge {
  min-width: 20px; height: 20px; padding: 0 6px;
  display: inline-grid; place-items: center;
  border-radius: 999px; background: var(--yellow); color: #2d3047;
  font-size: .72rem; font-weight: 800;
}
.nav-toggle { display: none; background: none; border: 0; padding: .5rem; cursor: pointer; }
.nav-toggle span { display: block; width: 26px; height: 3px; margin: 5px 0; border-radius: 3px; background: var(--purple); transition: transform .25s, opacity .25s; }
.nav-toggle.open span:nth-child(1) { transform: translateY(8px) rotate(45deg); }
.nav-toggle.open span:nth-child(2) { opacity: 0; }
.nav-toggle.open span:nth-child(3) { transform: translateY(-8px) rotate(-45deg); }

/* ===== Hero (home) ===== */
.hero {
  position: relative; overflow: hidden;
  padding: 5rem 0 6.5rem;
  background: var(--grad-main);
  color: #fff;
}
.hero-inner { position: relative; z-index: 1; text-align: center; }
.hero h1 { font-size: clamp(2rem, 5vw, 3.4rem); }
.hero-sub { font-size: 1.15rem; max-width: 620px; margin: 0 auto 2rem; opacity: .95; }
.eyebrow {
  display: inline-block; margin: 0 0 1rem;
  padding: .35rem 1rem; border-radius: 999px;
  background: rgba(255, 255, 255, .2); font-weight: 600; font-size: .9rem;
}
.hero-search {
  display: flex; gap: .5rem;
  max-width: 640px; margin: 0 auto 1.5rem; padding: .45rem;
  background: #fff; border-radius: 999px; box-shadow: var(--shadow-lg);
}
.hero-search input { flex: 1; min-width: 0; border: 0; padding: .6rem 1.1rem; font: inherit; font-size: 1rem; background: transparent; outline: none; color: var(--text); }
.hero-actions { display: flex; flex-wrap: wrap; gap: .75rem; justify-content: center; }
.blob { position: absolute; border-radius: 50%; filter: blur(60px); opacity: .55; animation: float 12s ease-in-out infinite; }
.blob-1 { width: 320px; height: 320px; background: #00cec9; top: -80px; left: -60px; }
.blob-2 { width: 260px; height: 260px; background: #fdcb6e; bottom: -90px; right: 10%; animation-delay: -4s; }
.blob-3 { width: 200px; height: 200px; background: #0984e3; top: 30%; right: -50px; animation-delay: -8s; }
@keyframes float { 50% { transform: translate(30px, -25px) scale(1.1); } }

/* ===== Page header (inner pages) ===== */
.page-header {
  padding: 3rem 0 4.5rem;
  background: linear-gradient(135deg, var(--from), var(--to));
  color: #fff;
  clip-path: ellipse(120% 100% at 50% 0%);
}
.page-header h1 { font-size: clamp(1.8rem, 4vw, 2.6rem); }
.page-header p { margin: 0; opacity: .95; font-size: 1.05rem; }

/* ===== Stat cards ===== */
.stats {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.25rem;
  margin-top: -3.5rem; position: relative; z-index: 2;
}
.stats.mini { margin-top: 0; }
.stat-card {
  display: flex; flex-direction: column; align-items: flex-start; gap: .15rem;
  padding: 1.25rem 1.4rem;
  background: var(--surface);
  border-radius: var(--radius);
  border-top: 5px solid var(--accent);
  box-shadow: var(--shadow);
}
.stat-card strong { font-size: 2rem; color: var(--accent); }
.stat-card strong.text-stat { font-size: 1.25rem; padding-block: .45rem; }
.stat-card span:last-child { color: var(--muted); font-size: .9rem; }
.stat-icon {
  width: 42px; height: 42px; display: grid; place-items: center;
  border-radius: 12px; font-size: 1.3rem;
  background: color-mix(in srgb, var(--accent) 15%, white);
}

/* ===== Section headings ===== */
.section-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; flex-wrap: wrap; margin-bottom: 1.25rem; }
.section-head h2 { margin: 0; }
.link-arrow { font-weight: 600; text-decoration: none; }
.link-arrow:hover { text-decoration: underline; }

/* ===== Department tiles ===== */
.dept-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 1rem; }
.dept-tile {
  display: flex; flex-direction: column; align-items: center; gap: .3rem;
  padding: 1.4rem 1rem; text-align: center; text-decoration: none; color: var(--text);
  border-radius: var(--radius);
  background: linear-gradient(160deg, color-mix(in srgb, var(--dept) 18%, white), #fff 70%);
  border: 2px solid color-mix(in srgb, var(--dept) 35%, white);
  transition: transform .2s, box-shadow .2s;
}
.dept-tile:hover { transform: translateY(-5px) rotate(-1deg); box-shadow: 0 12px 26px color-mix(in srgb, var(--dept) 35%, transparent); }
.dept-icon { font-size: 2rem; }
.dept-name { font-weight: 700; }
.dept-count { font-size: .8rem; color: var(--muted); }

/* ===== Steps ===== */
.steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.25rem; margin-top: 1.5rem; }
.step { background: var(--surface); border-radius: var(--radius); padding: 1.5rem; box-shadow: var(--shadow); border-bottom: 5px solid var(--accent); }
.step-num {
  display: grid; place-items: center; width: 44px; height: 44px; margin-bottom: .75rem;
  border-radius: 50%; background: var(--accent); color: #fff; font-weight: 800; font-size: 1.2rem;
}
.step p { margin: 0; color: var(--muted); }

/* ===== Filter panel ===== */
.filter-panel {
  margin-top: -2.5rem; position: relative; z-index: 2;
  padding: 1.5rem; background: var(--surface);
  border-radius: var(--radius); box-shadow: var(--shadow-lg);
}
.search-box { position: relative; margin-bottom: 1rem; }
.search-box.small { margin: 0; flex: 1; }
.search-icon { position: absolute; left: 1rem; top: 50%; transform: translateY(-50%); pointer-events: none; }
.search-box input {
  width: 100%; padding: .9rem 1rem .9rem 2.8rem;
  border: 2px solid var(--border); border-radius: 999px;
  font: inherit; font-size: 1rem; background: #faf9ff;
  transition: border-color .2s, box-shadow .2s;
}
.search-box.small input { padding-block: .6rem; }
.search-box input:focus { outline: none; border-color: var(--purple); box-shadow: 0 0 0 4px rgba(108, 92, 231, .15); }
.filters { display: grid; grid-template-columns: repeat(5, 1fr); gap: 1rem; }
.filter label { display: block; font-size: .8rem; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin-bottom: .3rem; }
select, .field input, .field select {
  width: 100%; padding: .65rem .9rem;
  border: 2px solid var(--border); border-radius: var(--radius-sm);
  background: #faf9ff; font: inherit; color: var(--text);
  transition: border-color .2s, box-shadow .2s;
}
select { cursor: pointer; }
select:focus, .field input:focus { outline: none; border-color: var(--purple); box-shadow: 0 0 0 4px rgba(108, 92, 231, .15); }
.filter-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 1rem; gap: 1rem; flex-wrap: wrap; }

/* Toggle switch */
.switch { display: inline-flex; align-items: center; gap: .6rem; cursor: pointer; font-weight: 600; }
.switch input { position: absolute; opacity: 0; }
.slider { position: relative; width: 46px; height: 26px; border-radius: 999px; background: #d8d4ef; transition: background .2s; }
.slider::after { content: ""; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: #fff; box-shadow: 0 2px 4px rgba(0,0,0,.2); transition: transform .2s; }
.switch input:checked + .slider { background: var(--green); }
.switch input:checked + .slider::after { transform: translateX(20px); }
.switch input:focus-visible + .slider { outline: 3px solid var(--yellow); outline-offset: 2px; }

.results-bar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; margin: 1.75rem 0 1rem; }
.result-count { margin: 0; font-weight: 700; font-size: 1.05rem; }
.active-filters { display: flex; flex-wrap: wrap; gap: .4rem; }
.filter-chip { padding: .3rem .8rem; border-radius: 999px; font-size: .8rem; font-weight: 600; background: #ede9ff; color: var(--purple); }

/* ===== Course cards ===== */
.course-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 1.5rem; margin-bottom: 3rem; }
.course-card {
  display: flex; flex-direction: column;
  padding: 1.4rem;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border-top: 6px solid var(--dept);
  position: relative; overflow: hidden;
  transition: transform .2s, box-shadow .2s;
  animation: pop .35s ease both;
}
.course-card::before {
  content: ""; position: absolute; top: -60px; right: -60px; width: 140px; height: 140px;
  border-radius: 50%; background: var(--dept); opacity: .1; pointer-events: none;
}
.course-card:hover { transform: translateY(-6px); box-shadow: 0 18px 36px color-mix(in srgb, var(--dept) 30%, transparent); }
@keyframes pop { from { opacity: 0; transform: translateY(12px) scale(.98); } }
.card-top { display: flex; justify-content: space-between; align-items: center; gap: .5rem; margin-bottom: .8rem; }
.dept-chip {
  display: inline-flex; align-items: center; gap: .3rem;
  padding: .25rem .7rem; border-radius: 999px;
  font-size: .78rem; font-weight: 700;
  background: color-mix(in srgb, var(--dept) 16%, white);
  color: color-mix(in srgb, var(--dept) 80%, black);
}
.credit-chip { padding: .2rem .6rem; border-radius: 8px; font-size: .78rem; font-weight: 800; background: var(--dept); color: #fff; }
.card-title { font-size: 1.15rem; }
.course-code { display: block; font-size: .85rem; color: var(--dept); letter-spacing: .05em; filter: brightness(.85); }
.card-desc { margin: 0 0 .9rem; color: var(--muted); font-size: .92rem; flex: 1; }
.card-meta { list-style: none; padding: 0; margin: 0 0 1rem; display: grid; gap: .25rem; font-size: .88rem; }
.capacity { display: flex; align-items: center; gap: .75rem; margin-bottom: 1rem; }
.capacity-bar { flex: 1; height: 8px; border-radius: 999px; background: #eeeaf8; overflow: hidden; }
.capacity-bar span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--dept), color-mix(in srgb, var(--dept) 55%, white)); }
.seat-badge { padding: .2rem .6rem; border-radius: 999px; font-size: .75rem; font-weight: 700; white-space: nowrap; }
.seat-badge.ok { background: #d5f5ec; color: #00795f; }
.seat-badge.low { background: #fff1d0; color: #9a6a00; }
.seat-badge.full { background: #ffe0e0; color: #b71c1c; }
.card-actions { display: flex; gap: .6rem; }
.card-actions .btn { flex: 1; }

/* ===== Cards / forms ===== */
.card { background: var(--surface); border-radius: var(--radius); box-shadow: var(--shadow); padding: 1.5rem; }
.register-layout { display: grid; grid-template-columns: 1fr 320px; gap: 1.5rem; align-items: start; margin-top: -2.5rem; position: relative; z-index: 2; }
.form-card fieldset { border: 0; padding: 0; margin: 0 0 1.75rem; }
.form-card fieldset:last-child { margin-bottom: 0; }
legend { display: flex; align-items: center; gap: .6rem; font-size: 1.2rem; font-weight: 700; margin-bottom: 1rem; padding: 0; }
.legend-num { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: var(--grad-main); color: #fff; font-size: .95rem; }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem 1.25rem; }
.field label { display: block; font-weight: 600; font-size: .9rem; margin-bottom: .3rem; }
.field-error { display: block; min-height: 1.1em; color: var(--red); font-size: .8rem; margin-top: .2rem; }
.field-error.block:empty { min-height: 0; margin: 0; }
.field.invalid input, .field.invalid select { border-color: var(--red); background: #fff5f5; }
.form-actions { display: flex; justify-content: flex-end; gap: .75rem; margin-top: 1.25rem; flex-wrap: wrap; }
.form-actions.full { grid-column: 1 / -1; margin-top: .25rem; }
.checkbox { display: flex; gap: .6rem; align-items: flex-start; cursor: pointer; }
.checkbox input { width: 18px; height: 18px; margin-top: .2rem; accent-color: var(--purple); }

.option-filters { display: flex; gap: .75rem; margin-bottom: 1rem; }
.option-filters select { width: auto; min-width: 180px; }
.course-options { display: grid; gap: .6rem; max-height: 440px; overflow-y: auto; padding: .25rem; margin: -.25rem; }
.course-option {
  display: flex; align-items: center; gap: .85rem;
  padding: .8rem 1rem;
  border: 2px solid var(--border); border-left: 6px solid var(--dept);
  border-radius: var(--radius-sm);
  cursor: pointer; transition: border-color .15s, background .15s, transform .15s;
}
.course-option:hover:not(.disabled) { transform: translateX(3px); border-color: color-mix(in srgb, var(--dept) 50%, white); border-left-color: var(--dept); }
.course-option:has(input:checked) { background: color-mix(in srgb, var(--dept) 10%, white); border-color: var(--dept); }
.course-option.disabled { opacity: .55; cursor: not-allowed; }
.course-option input { width: 20px; height: 20px; flex-shrink: 0; accent-color: var(--dept); }
.option-body { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.option-title { font-size: .95rem; }
.option-meta { font-size: .8rem; color: var(--muted); }

.summary-card { position: sticky; top: calc(var(--nav-h) + 1rem); border-top: 6px solid var(--teal); }
.summary-row { display: flex; justify-content: space-between; gap: 1rem; padding: .45rem 0; font-size: .92rem; }
.summary-row.total { border-top: 2px dashed var(--border); margin-top: .4rem; padding-top: .7rem; font-size: 1rem; }
.credit-meter { height: 12px; border-radius: 999px; background: #eeeaf8; overflow: hidden; margin: .6rem 0; }
.credit-meter span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--green), var(--teal), var(--blue)); transition: width .3s; }
.credit-meter.over span { background: linear-gradient(90deg, var(--orange), var(--red)); }
.warning-list { list-style: none; padding: .7rem .9rem; margin: .75rem 0 0; background: #fff6e5; border-radius: var(--radius-sm); font-size: .82rem; color: #8a5a00; display: grid; gap: .3rem; }

/* ===== Data table ===== */
.table-card { padding: 0; overflow: hidden; }
.table-wrap { overflow-x: auto; }
.data-table { width: 100%; border-collapse: collapse; font-size: .92rem; }
.data-table thead th {
  text-align: left; padding: 1rem; white-space: nowrap;
  background: var(--grad-main); color: #fff; font-weight: 700; font-size: .82rem; text-transform: uppercase; letter-spacing: .04em;
}
.data-table td { padding: .9rem 1rem; border-bottom: 1px solid var(--border); }
.data-table tbody tr { transition: background .15s; }
.data-table tbody tr:nth-child(even) { background: #faf9ff; }
.data-table tbody tr:hover { background: color-mix(in srgb, var(--dept) 8%, white); }
.data-table tbody td:first-child { border-left: 5px solid var(--dept); }
.data-table tfoot td { padding: 1rem; font-weight: 600; background: #f3f0ff; }
.code-pill { display: inline-block; padding: .2rem .6rem; border-radius: 8px; background: var(--dept); color: #fff; font-weight: 700; font-size: .8rem; }

.empty-state { text-align: center; padding: 2.5rem 1.5rem; }
.empty-state.wide { grid-column: 1 / -1; background: var(--surface); border-radius: var(--radius); box-shadow: var(--shadow); }
.empty-icon { font-size: 3rem; margin-bottom: .5rem; }
.empty-state p { color: var(--muted); }

/* ===== Profile ===== */
.profile-layout { display: grid; grid-template-columns: 320px 1fr; gap: 1.5rem; align-items: start; margin-top: -2.5rem; position: relative; z-index: 2; }
.profile-main { display: grid; gap: 1.5rem; min-width: 0; }
.profile-card { text-align: center; position: relative; overflow: hidden; padding-top: 0; }
.profile-card::before { content: ""; display: block; height: 90px; margin: 0 -1.5rem; background: linear-gradient(135deg, #e84393, #fdcb6e, #00cec9); }
.avatar {
  width: 104px; height: 104px; margin: -52px auto .75rem;
  display: grid; place-items: center; border-radius: 50%;
  background: var(--grad-main); color: #fff; font-size: 2.2rem; font-weight: 800;
  border: 5px solid #fff; box-shadow: var(--shadow);
}
.profile-card h2 { margin-bottom: .2rem; }
.profile-info { list-style: none; padding: 0; margin: 1.25rem 0 0; text-align: left; display: grid; gap: .6rem; }
.profile-info li { display: flex; flex-direction: column; padding: .65rem .85rem; border-radius: var(--radius-sm); background: #faf9ff; }
.profile-info li:nth-child(1) { border-left: 4px solid var(--purple); }
.profile-info li:nth-child(2) { border-left: 4px solid var(--blue); }
.profile-info li:nth-child(3) { border-left: 4px solid var(--green); }
.profile-info li:nth-child(4) { border-left: 4px solid var(--pink); }
.profile-info span { font-size: .78rem; color: var(--muted); }
.profile-info strong { word-break: break-word; }

.weekly-schedule { display: grid; grid-template-columns: repeat(5, 1fr); gap: .75rem; }
.day-col { background: #faf9ff; border-radius: var(--radius-sm); padding: .75rem; min-height: 140px; }
.day-col h4 { text-align: center; margin-bottom: .6rem; color: var(--purple); }
.slot {
  display: flex; flex-direction: column; padding: .55rem .65rem; margin-bottom: .5rem;
  border-radius: 8px; font-size: .8rem;
  background: color-mix(in srgb, var(--dept) 15%, white);
  border-left: 4px solid var(--dept);
}
.slot strong { color: color-mix(in srgb, var(--dept) 75%, black); }
.slot small { color: var(--muted); }
.slot-empty { text-align: center; font-size: .8rem; color: var(--muted); margin: 1.5rem 0 0; }

.edit-card summary { cursor: pointer; list-style: none; display: flex; align-items: center; justify-content: space-between; }
.edit-card summary::-webkit-details-marker { display: none; }
.edit-card summary::after { content: "▾"; font-size: 1.2rem; color: var(--purple); transition: transform .2s; }
.edit-card[open] summary::after { transform: rotate(180deg); }
.edit-card summary h3 { margin: 0; }
.edit-card[open] summary { margin-bottom: 1.25rem; }

/* ===== Modal ===== */
.modal-overlay {
  position: fixed; inset: 0; z-index: 100;
  display: grid; place-items: center; padding: 1rem;
  background: rgba(45, 48, 71, .55); backdrop-filter: blur(4px);
  opacity: 0; transition: opacity .2s;
}
.modal-overlay[hidden] { display: none; }
.modal-overlay.show { opacity: 1; }
.modal {
  width: min(520px, 100%); max-height: 90vh; overflow-y: auto;
  background: var(--surface); border-radius: 20px; box-shadow: 0 30px 70px rgba(0, 0, 0, .3);
  transform: translateY(20px) scale(.96); transition: transform .25s cubic-bezier(.2, .9, .3, 1.3);
}
.modal-overlay.show .modal { transform: none; }
.modal-header {
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  padding: 1.1rem 1.5rem; background: var(--grad-main); color: #fff;
}
.modal-error .modal-header { background: linear-gradient(135deg, #d63031, #e17055); }
.modal-header h2 { margin: 0; font-size: 1.2rem; }
.modal-close { background: rgba(255, 255, 255, .2); border: 0; color: #fff; width: 34px; height: 34px; border-radius: 50%; font-size: 1.4rem; line-height: 1; cursor: pointer; }
.modal-close:hover { background: rgba(255, 255, 255, .35); }
.modal-body { padding: 1.5rem; }
.modal-body > p:first-child { margin-top: 0; }
.modal-footer { display: flex; justify-content: flex-end; gap: .75rem; padding: 0 1.5rem 1.5rem; flex-wrap: wrap; }
.confirm-list { list-style: none; padding: 0; margin: 0 0 1rem; display: grid; gap: .5rem; }
.confirm-list li { display: flex; flex-direction: column; padding: .7rem .9rem; border-radius: var(--radius-sm); background: color-mix(in srgb, var(--dept) 12%, white); border-left: 5px solid var(--dept); }
.confirm-list small { color: var(--muted); }
.confirm-total { display: flex; justify-content: space-between; padding: .8rem 1rem; border-radius: var(--radius-sm); background: #f3f0ff; }
.confirm-total strong { color: var(--purple); }
.error-list { padding-left: 1.2rem; color: #b71c1c; display: grid; gap: .3rem; }
.details p { color: var(--muted); }
.details-grid { display: grid; grid-template-columns: auto 1fr; gap: .5rem 1rem; margin: 0; }
.details-grid dt { font-weight: 700; color: var(--dept); filter: brightness(.85); }
.details-grid dd { margin: 0; display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; }

/* ===== Toasts ===== */
.toast-stack { position: fixed; bottom: 1.25rem; right: 1.25rem; z-index: 200; display: grid; gap: .5rem; }
.toast {
  padding: .85rem 1.2rem; border-radius: 12px; color: #fff; font-weight: 600;
  box-shadow: 0 10px 30px rgba(0, 0, 0, .2);
  animation: slideIn .3s ease both; transition: opacity .3s, transform .3s;
}
.toast.hide { opacity: 0; transform: translateX(30px); }
.toast-success { background: linear-gradient(135deg, #00b894, #00cec9); }
.toast-warn { background: linear-gradient(135deg, #e17055, #fdcb6e); }
.toast-error { background: linear-gradient(135deg, #d63031, #e84393); }
@keyframes slideIn { from { opacity: 0; transform: translateX(30px); } }

/* ===== Footer ===== */
.footer { margin-top: 3rem; padding: 2rem 0; background: #2d3047; color: #e8e6f5; border-top: 5px solid transparent; border-image: var(--grad-main) 1; }
.footer-inner { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; }
.footer p { margin: 0; }
.footer .muted { color: #a9a7c4; }
.footer a { color: #81ecec; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .filters { grid-template-columns: repeat(3, 1fr); }
  .steps { grid-template-columns: repeat(2, 1fr); }
  .register-layout, .profile-layout { grid-template-columns: 1fr; }
  .summary-card { position: static; order: -1; }
  .profile-card { max-width: 520px; width: 100%; margin-inline: auto; }
}

@media (max-width: 860px) {
  .nav-toggle { display: block; }
  .nav-menu {
    position: absolute; top: var(--nav-h); left: 0; right: 0;
    flex-direction: column; gap: .25rem; padding: 1rem;
    background: #fff; box-shadow: 0 16px 30px rgba(0, 0, 0, .1);
    transform: translateY(-10px); opacity: 0; visibility: hidden;
    transition: transform .2s, opacity .2s, visibility .2s;
  }
  .nav-menu.open { transform: none; opacity: 1; visibility: visible; }
  .nav-link { padding: .8rem 1rem; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .weekly-schedule { grid-template-columns: 1fr; }
  .day-col { min-height: 0; }
  .slot-empty { margin: 0; }

  /* Data table collapses into stacked cards */
  .data-table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
  .data-table, .data-table tbody, .data-table tr, .data-table td, .data-table tfoot { display: block; width: 100%; }
  .data-table tbody tr { border-left: 6px solid var(--dept); border-bottom: 1px solid var(--border); padding: .5rem 0; }
  .data-table tbody td:first-child { border-left: 0; }
  .data-table td { display: flex; justify-content: space-between; gap: 1rem; padding: .45rem 1rem; border: 0; text-align: right; }
  .data-table td::before { content: attr(data-label); font-weight: 700; color: var(--muted); text-align: left; }
  .data-table tfoot tr { display: flex; justify-content: space-between; }
  .data-table tfoot td { width: auto; }
}

@media (max-width: 600px) {
  .container { width: calc(100% - 1.5rem); }
  .hero { padding: 3.5rem 0 5.5rem; }
  .hero-search { flex-direction: column; border-radius: var(--radius); }
  .hero-search .btn { width: 100%; }
  .filters, .form-grid { grid-template-columns: 1fr; }
  .option-filters { flex-direction: column; }
  .option-filters select { width: 100%; }
  .stats { gap: .75rem; }
  .stat-card { padding: 1rem; }
  .stat-card strong { font-size: 1.6rem; }
  .steps { grid-template-columns: 1fr; }
  .course-grid { grid-template-columns: 1fr; }
  .form-actions { flex-direction: column-reverse; }
  .form-actions .btn { width: 100%; }
  .modal-footer .btn { flex: 1; }
  .course-option { flex-wrap: wrap; }
  .toast-stack { left: .75rem; right: .75rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
