  p.on('console', m => m.type() === 'error' && errors.push(m.text()));
  const B = 'http://localhost:8765/';
  await p.goto(B + 'index.html'); await p.waitForTimeout(1000);
  await p.screenshot({ path: 'home.png', fullPage: true });
  await p.goto(B + 'catalog.html?q=data');
  console.log('catalog q=data:', await p.textContent('#result-count'));
  await p.click('#reset-filters');
  await p.selectOption('#filter-dept', 'CS');
  console.log('CS:', await p.textContent('#result-count'));
  await p.click('#reset-filters');
  await p.click('[data-action=register][data-id=CS101]');
  await p.waitForTimeout(300);
  await p.click('.modal-footer .btn-primary'); await p.waitForTimeout(300);
  // conflict: BUS101 Mon/Wed 11:00 vs MATH310 Mon/Wed 10:30
  await p.click('[data-action=details][data-id=MATH310]'); await p.waitForTimeout(300);
  await p.click('.modal-footer .btn-primary'); await p.waitForTimeout(300);
  await p.click('.modal-footer .btn-primary'); await p.waitForTimeout(300);
  await p.screenshot({ path: 'catalog.png' });
  await p.goto(B + 'register.html');
  await p.check('input[value=BUS101]');
  console.log('summary warnings:', await p.textContent('#selection-summary'));
  await p.uncheck('input[value=BUS101]');
  await p.check('input[value=ART250]'); await p.check('input[value=ENG280]');
  await p.check('input[name=agree]');
  await p.click('button[type=submit]'); await p.waitForTimeout(300);
  console.log('modal:', (await p.textContent('.modal-body')).replace(/\s+/g,' ').trim());
  await p.click('.modal-footer .btn-primary'); await p.waitForTimeout(500);
  console.log('rows:', await p.locator('#registered-table tbody tr').count());
  await p.screenshot({ path: 'register.png', fullPage: true });
  await p.goto(B + 'profile.html'); await p.waitForTimeout(300);
  console.log('profile credits:', await p.textContent('#p-credits'), await p.textContent('#p-status'));
  await p.screenshot({ path: 'profile.png', fullPage: true });
  await p.setViewportSize({ width: 390, height: 844 });
  await p.click('.nav-toggle'); await p.waitForTimeout(300);
  await p.screenshot({ path: 'mobile-profile.png', fullPage: true });
  await p.goto(B + 'catalog.html'); await p.screenshot({ path: 'mobile-catalog.png' });
  const sw = await p.evaluate(() => document.documentElement.scrollWidth);
  console.log('mobile scrollWidth', sw);
  console.log('errors:', errors);
  await b.close();
})();
EOF
