const { JSDOM } = require('jsdom');
const fs = require('fs');
const store = {};
const wait = (ms) => new Promise(r => setTimeout(r, ms));
async function load(page, query = '') {
  let html = fs.readFileSync('/work/' + page, 'utf8').replace(/<script src="[^"]+"><\/script>/g, '');
  const dom = new JSDOM(html, { url: 'http://localhost/' + page + query, runScripts: 'outside-only', pretendToBeVisual: true });
  const w = dom.window;
  Object.entries(store).forEach(([k, v]) => w.localStorage.setItem(k, v));
  w.HTMLElement.prototype.scrollIntoView = () => {};
  const errs = [];
  w.addEventListener('error', e => errs.push(e.message));
  w.eval(fs.readFileSync('/work/js/data.js', 'utf8') + '\n;window.COURSES=COURSES;window.DEPARTMENTS=DEPARTMENTS;');
  w.eval(fs.readFileSync('/work/js/app.js', 'utf8'));
  w.document.dispatchEvent(new w.Event('DOMContentLoaded'));
  await wait(50);
  const save = () => { for (let i = 0; i < w.localStorage.length; i++) { const k = w.localStorage.key(i); store[k] = w.localStorage.getItem(k); } };
  return { w, d: w.document, errs, save };
}
const txt = (el) => el.textContent.replace(/\s+/g, ' ').trim();
(async () => {
  let { w, d, errs, save } = await load('index.html');
  console.log('home cards', d.querySelectorAll('#featured-grid .course-card').length, 'depts', d.querySelectorAll('.dept-tile').length, 'nav', d.querySelectorAll('.nav-link').length, errs);

  ({ w, d, errs, save } = await load('catalog.html', '?q=data'));
  console.log(txt(d.querySelector('#result-count')));
  d.querySelector('#reset-filters').click();
  d.querySelector('#filter-dept').value = 'CS'; d.querySelector('#filter-dept').dispatchEvent(new w.Event('change'));
  console.log('CS', txt(d.querySelector('#result-count')));
  d.querySelector('#filter-open').checked = true; d.querySelector('#filter-open').dispatchEvent(new w.Event('change'));
  console.log('CS open', txt(d.querySelector('#result-count')), txt(d.querySelector('#active-filters')));
  d.querySelector('#reset-filters').click();
  d.querySelector('[data-action=register][data-id=CS101]').click(); await wait(30);
  console.log('modal:', txt(d.querySelector('#modal-title')));
  d.querySelector('.modal-footer .btn-primary').click(); await wait(250);
  console.log('CS101 card btn:', txt(d.querySelector('.course-card[data-id=CS101] .card-actions')), 'badge', d.querySelector('#nav-badge').textContent);
  d.querySelector('[data-action=details][data-id=MATH310]').click(); await wait(30);
  d.querySelector('.modal-footer .btn-primary').click(); await wait(30);
  console.log('after details->register, hidden?', d.querySelector('#modal').hidden, txt(d.querySelector('#modal-title')));
  await wait(250);
  console.log('still open after close timer?', !d.querySelector('#modal').hidden);
  d.querySelector('.modal-footer .btn-primary').click(); await wait(250);
  d.querySelector('[data-action=register][data-id=BUS101]').click(); await wait(30);
  console.log('conflict modal:', txt(d.querySelector('.modal-body')));
  save(); console.log(errs);

  ({ w, d, errs, save } = await load('register.html'));
  console.log('name prefill', d.querySelector('#name').value, 'options', d.querySelectorAll('.course-option').length, 'rows', d.querySelectorAll('#registered-table tbody tr').length);
  d.querySelector('button[type=submit]').click(); await wait(30);
  console.log('errors:', txt(d.querySelector('#courses-error')), '|', txt(d.querySelector('#agree-error')));
  for (const id of ['ART250', 'ENG280']) { const i = d.querySelector(`input[value=${id}]`); i.checked = true; i.dispatchEvent(new w.Event('change', { bubbles: true })); }
  console.log('summary:', txt(d.querySelector('#selection-summary')));
  d.querySelector('input[name=agree]').checked = true;
  d.querySelector('button[type=submit]').click(); await wait(30);
  console.log('confirm:', txt(d.querySelector('.modal-body')));
  d.querySelector('.modal-footer .btn-primary').click(); await wait(250);
  console.log('rows', d.querySelectorAll('#registered-table tbody tr').length, txt(d.querySelector('#registered-table tfoot')));
  d.querySelector('[data-drop=ART250]').click(); await wait(30);
  d.querySelector('.modal-footer .btn-danger').click(); await wait(250);
  console.log('after drop rows', d.querySelectorAll('#registered-table tbody tr').length);
  save(); console.log(errs);

  ({ w, d, errs, save } = await load('profile.html'));
  console.log('profile', txt(d.querySelector('#p-courses')), txt(d.querySelector('#p-credits')), txt(d.querySelector('#p-status')), 'slots', d.querySelectorAll('.slot').length);
  d.querySelector('#p-phone').value = '555-1234';
  d.querySelector('#profile-form').dispatchEvent(new w.Event('submit', { cancelable: true }));
  console.log('card phone:', txt(d.querySelector('#profile-card')).includes('555-1234'), errs);
  process.exit(0);
})();
EOF
